function halfUp(string \$v, int \$scale): string {
    if (\$scale < 0) { \$scale = 0; }
    // Multiply v by 10^scale
    \$scalePow = (string) pow(10, \$scale);
    \$scaled = bcmath::mul(\$v, \$scalePow, 0); // full precision, no rounding (scale=0)
    // Integer part and remainder of scaled value
    \$intPart = (string) bcdiv(\$scaled, '1', 0); // integer
    \$fracScaled = bcmod(\$scaled, '1', 0); // remainder (integer digits, scale 0)
    // fracScaled is like '7' (0.7) or '75' (0.75)
    // Actually bcmod with scale=0 gives integer remainder
    // scaled = 1426249875, intPart = 1426249875, fracScaled = 0
    // Wait, bcdiv('1426249875','1',0) = 1426249875, bcmod = 0
    // We need to handle the fractional part of the *scaled* value
    // Better: bcmod(\$scaled, '1', 0) with \$scaled = '14262498.75'
    // bcmod('14262498.75','1',0) = 0.75 (scale 0 -> 0.75)
    echo 'scaled: \$scaled' . PHP_EOL;
    \$remainder = bcmod(\$scaled, '1', 0);
    echo 'remainder: \$remainder' . PHP_EOL;
    \$half = (string) bcdiv('1', '2', \$scale);
    // remainder is in units of 1 (not 10^-scale)
    // Compare remainder with 0.5
    if (bccomp(\$remainder, \$half, \$scale) >= 0) {
        return bcadd(\$intPart, '1', 0);
    }
    return \$intPart;
}
echo halfUp('2.5', 0) . PHP_EOL;
